import { useEffect, useState } from "react";
import { BASE_URL } from '@/config';
export default function UserManagement() {
    const [users, setUsers] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");

    useEffect(() => {
        fetchUsers();
    }, []);

    // Fetch users from backend
    const fetchUsers = async () => {
        try {
            const token = localStorage.getItem("token");
            const res = await fetch(`${BASE_URL}/users`, {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            });

            if (!res.ok) {
                const data = await res.json();
                throw new Error(data.message || "Failed to fetch users");
            }

            const data = await res.json();
            setUsers(data.users);
        } catch (err: any) {
            console.error(err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    // Toggle block/unblock user
    const toggleBlock = async (userId: string, block: boolean) => {
        try {
            const token = localStorage.getItem("token");
            const res = await fetch(`${BASE_URL}/users/${userId}/block`, {
                method: "PATCH",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ isBlocked: block }),
            });

            if (!res.ok) {
                const data = await res.json();
                throw new Error(data.message || "Failed to update status");
            }

            setUsers((prev) =>
                prev.map((user: any) =>
                    user._id === userId ? { ...user, isBlocked: block } : user
                )
            );
        } catch (err: any) {
            alert(err.message);
        }
    };

    // Render users
    if (loading) return <p className="p-8">Loading users...</p>;
    if (error) return <p className="p-8 text-red-500">{error}</p>;



    return (
        <div className="p-8 bg-gray-50 min-h-screen">
            <h1 className="text-2xl font-bold mb-6 text-gray-900">Users Management</h1>

            <table className="min-w-full bg-white border border-gray-200 shadow-sm rounded-lg">
                <thead className="bg-gray-100">
                    <tr>
                        <th className="py-3 px-4 border-b text-left text-gray-700">Full Name</th>
                        <th className="py-3 px-4 border-b text-left text-gray-700">Email</th>
                        <th className="py-3 px-4 border-b text-left text-gray-700">Phone</th>
                        <th className="py-3 px-4 border-b text-left text-gray-700">Role</th>
                        <th className="py-3 px-4 border-b text-left text-gray-700">Status</th>
                        <th className="py-3 px-4 border-b text-left text-gray-700">Action</th>
                    </tr>
                </thead>

                <tbody>
                    {users.map((user: any) => (
                        <tr key={user._id} className="hover:bg-gray-50">
                            <td className="py-3 px-4 border-b">{user.fullName}</td>
                            <td className="py-3 px-4 border-b">{user.email}</td>
                            <td className="py-3 px-4 border-b">{user.phone}</td>
                            <td className="py-3 px-4 border-b capitalize">{user.role}</td>
                            <td className="py-3 px-4 border-b">
                                {user.isBlocked ? "Blocked" : "Active"}
                            </td>
                            <td className="py-3 px-4 border-b space-x-2">
                                <button
                                    onClick={() => toggleBlock(user._id, !user.isBlocked)}
                                    className={`px-3 py-1 rounded-md text-white ${user.isBlocked ? "bg-green-500" : "bg-red-500"
                                        }`}
                                >
                                    {user.isBlocked ? "Unblock" : "Block"}
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}